@use 'abstracts' as *;

.c-careers-banner {
  background-color: #006633;
  background-image: var(--careers-banner-image);
  background-position: center;
  background-size: cover;
  color: $white;
  border-radius: 20px;
  min-height: 150px;
  overflow: hidden;
  width: 100%;

  &__inner { align-items: center; display: flex; flex-direction: column; justify-content: center; min-height: 150px; width: 100%; }
  h1 { font-size: 48px; font-weight: 700; line-height: 1; margin: 0; }
}

.c-careers-heading { margin-top: 24px; }
.c-careers-breadcrumb { align-items: center; display: flex; font-size: 14px; height: 70px; margin: 0; }
.c-careers-vacancies { margin: 48px auto 0; max-width: 1196px; }
.c-careers-vacancies__list { display: grid; gap: 20px; }

.c-career-vacancy {
  background: #f6f6f6;
  border: 1px solid #c8c8c8;
  border-radius: 30px;
  overflow: hidden;

  box-sizing: border-box;
  height: 114px;

  summary { align-items: center; background: #006633; box-sizing: border-box; color: $white; cursor: pointer; display: flex; font-size: 24px; font-weight: 700; height: 114px; justify-content: space-between; line-height: 24px; list-style: none; padding: 30px 50px 30px 56px; }
  summary::-webkit-details-marker { display: none; }
  &__icon { border: solid currentColor; border-width: 0 2px 2px 0; height: 12px; transform: rotate(45deg); transition: transform .2s ease; width: 12px; }
  &[open] .c-career-vacancy__icon { transform: rotate(225deg); }
  &__body { padding: 40px 100px 59px; }
  &__description { color: #11111b; font-size: 18px; line-height: 21px; margin-inline: -40px; }
  &__description p { margin: 0 0 24px; }
  &__description ul { list-style: disc outside; margin: -8px 0 24px; padding-left: 20px; }
  &__description li { margin: 0 0 3px; }
}

.c-career-vacancy:first-child { height: auto; margin-bottom: 5px; }
.c-career-vacancy:not(:first-child) { border-color: transparent; }

.c-career-application {
  margin-top: 30px;
  .wpcf7 { color: #11111b; }
  .wpcf7 form { color: #11111b; display: grid; gap: 30px; grid-template: 'contact contact' 152px 'upload consents' 90px 'empty submit' 44px / 223px 1fr; margin: 0; }
  .wpcf7 p { margin: 0; }
  .wpcf7 label { display: block; font-size: 18px; }
  .wpcf7-form-control-wrap { display: block; }
  input:not([type='checkbox']):not([type='submit']) { background: $white; border: 1px solid #c8c8c8; border-radius: 15px; color: #11111b; font: inherit; height: 62px; padding: 0 20px; text-align: left; width: 100%; }
  input:not([type='checkbox']):not([type='submit'])::placeholder { color: #b3b3b3; text-align: left; }
  .c-careers-form__contact { display: grid; gap: 26px 20px; grid-area: contact; grid-template-columns: repeat(2, 1fr); }
  .c-careers-form__contact > p:first-child { grid-column: 1 / -1; }
  .c-careers-form__upload { grid-area: upload; position: relative; }
  .c-careers-form__upload label { align-items: center; border: 1px solid #11111b; border-radius: 24px; cursor: pointer; display: flex; font-size: 16px; font-weight: 700; height: 44px; justify-content: center; position: relative; width: 223px; }
  .c-careers-form__upload label::after { border: solid #11111b; border-width: 0 2px 2px 0; content: ''; height: 8px; margin-left: 18px; transform: rotate(45deg) translateY(-2px); width: 8px; }
  .c-careers-form__upload input[type='file'] { cursor: pointer; height: 44px; inset: 0; opacity: 0; position: absolute; width: 223px; }
  .c-careers-form__consents { display: grid; font-size: 14px; gap: 12px; grid-area: consents; line-height: 1.35; }
  .c-careers-form__consents label { align-items: flex-start; display: flex; font-size: inherit; gap: 10px; }
  .c-careers-form__consents input { accent-color: #056839; height: 14px; margin-top: 3px; width: 14px; }
  .c-careers-form__submit { grid-area: submit; justify-self: end; }
  .wpcf7-response-output { display: none; }
  input[type='submit'] { background: #056839; border: 0; border-radius: 30px; color: $white; font: inherit; font-weight: 700; min-height: 44px; min-width: 221px; padding: 0 30px; }
}

.c-careers-cta { background: #006633 var(--careers-cta-background) center / cover no-repeat; color: $white; margin: 143px 0 39px 36px; min-height: 230px; width: calc(100% - 80px); }
.c-careers-cta__inner { align-items: center; display: flex; gap: 250px; justify-content: flex-start; margin: 0 auto; min-height: 230px; padding: 30px 30px 30px 292px; text-align: left; }
.c-careers-cta h2 { font-size: 48px; font-weight: 700; line-height: normal; margin: 0; max-width: 750px; }
.c-careers-cta__button { align-items: center; border: 1px solid $white; border-radius: 30px; box-sizing: border-box; color: $white; display: inline-flex; font-weight: 700; height: 44px; justify-content: center; padding: 0 30px; text-decoration: none; white-space: nowrap; width: 223px; }

@include media($breakpoint-md) {
  .c-careers-vacancies { margin-inline: 20px; }
  .c-career-vacancy__body { padding-inline: 40px; }
  .c-careers-cta { margin-inline: 20px; }
  .c-careers-cta h2 { font-size: 36px; }
}

@include media($breakpoint-sm) {
  .c-careers-banner, .c-careers-banner__inner { min-height: 180px; }
  .c-careers-banner h1 { font-size: 38px; }
  .c-career-vacancy summary { font-size: 19px; min-height: 86px; padding: 22px 25px; }
  .c-career-vacancy__body { padding: 30px 25px; }
  .c-career-application .c-careers-form__contact { grid-template-columns: 1fr; }
  .c-career-application .c-careers-form__contact > p:first-child { grid-column: auto; }
  .c-career-application .wpcf7 form { display: flex; }
  .c-career-application .c-careers-form__submit { align-self: start; }
  .c-careers-cta { margin-inline: 0; }
  .c-careers-cta__inner { align-items: flex-start; flex-direction: column; gap: 24px; padding: 30px; }
  .c-careers-cta h2 { font-size: 30px; max-width: none; }
}

